// Ajusta o fim da seção: corta seções longas num fim de parágrafo e evita terminar no fim do documento.
function fFimUtil(md, inicio, fim) {
  const parag = [];
  let i = md.indexOf('\n\n', inicio + 1);
  while (i >= 0 && i < fim) {
    parag.push(i + 2);
