function fDocumentos(escolhidas, candidatos, assunto, hoje) {
  return escolhidas.map((e, i) => {
    const c = candidatos.find((x) => x.id === e.id);
    return {
      id: 'F' + (i + 1),
      assunto,
      url: c.url_final,
      titulo: c.titulo || c.dominio,
