  const add = (url, origem, meta) => {
    if (vistos.has(url) || out.length >= 8) return;
    vistos.add(url);
    out.push({ id: 'C' + (out.length + 1), url_serp: url, origem, titulo: meta.titulo || null, rank: meta.rank || null, website_name: meta.website_name || null });
