    const google = /(^|\.)google\./u.test(host || '');
    if (!google && (fExcluido(host) || host === cliente)) continue;
    if (/reddit|youtube|instagram|facebook|tiktok|pinterest|quora/iu.test(String(r.website_name || ''))) continue;
